SELECT CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END AS opened_cohort, customer_id, SUM(CASE WHEN account_type = 'CREDIT' THEN balance ELSE 0 END) AS credit_balance FROM accounts WHERE NOT (balance <= 76000 AND (account_type NOT IN ('CHECKING', 'CREDIT', 'LOAN') OR opened_date BETWEEN '2025-03-30' AND '2025-09-01')) GROUP BY CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END, customer_id;
